# entrypoint module
def begin(out_dir: str, cache_dir: str, schema_version: str, progress) -> "Session":
    """Open a calculation session. Called once per run."""

class Session:
    def add_file(self, name: str, mtime_ms: int, size: int, path: str) -> str:
        """The user's file is already at `path`. Return exactly one of:
        "parsed"  — the file was parsed now (aggregates updated);
        "cached"  — the file was recognised from the cache, parsing skipped;
        "service" — a service file (reference table, override): the engine keeps
                    it on disk until finish() ends; all others are deleted
                    IMMEDIATELY after the return — do not keep the path."""

    def finish(self) -> dict:
        """Write the outputs into out_dir and return their names (relative to out_dir):
        {"html": "dashboard.html" | None,
         "slots": {"0": "sales_data.bin.gz", ...},
         "write_back": {"1": "sales_review.xlsx"} | {}}"""

import pandas as pd

def begin(out_dir, cache_dir, schema_version, progress):
    return Session(out_dir, progress)

class Session:
    def __init__(self, out_dir, progress):
        self.out_dir = out_dir
        self.progress = progress
        self.totals = {}
        self.ref_path = None

    def add_file(self, name, mtime_ms, size, path):
        if name.lower() == "regions.xlsx":        # region reference table
            self.ref_path = path                  # we'll read it later, in finish()
            return "parsed"
        df = pd.read_excel(path, sheet_name="Data")
        for i, row in enumerate(df.itertuples()):
            self.progress("rows", i, len(df), name)
            key = row.region
            self.totals[key] = self.totals.get(key, 0) + row.qty
        return "parsed"

