{
  "name": "sales-weekly",
  "version": "1.4.0",
  "entrypoint": { "module": "sales_weekly.engine" },
  "deps": [
    { "name": "pandas",          "version": "3.0.3" },
    { "name": "python-calamine", "version": "0.8.2" }
  ],
  "inputs": [
    { "match": "Sales_2026_w*.xlsx", "role": "data", "required": true,
      "sheets": [ { "name": "Data", "columns": ["Customer code", "Region", "Qty"] } ] },
    { "match": "Regions.xlsx", "role": "reference" }
  ],
  "outputs": {
    "html": true,
    "slots": [
      { "index": 0, "name": "sales_data.bin.gz", "type": "data" },
      { "index": 1, "name": "sales_review.xlsx", "type": "xlsx", "write_back": true }
    ]
  },
  "required_files": ["Regions.xlsx"],
  "aux_inputs": [
    { "name": "sales_review_filled.xlsx", "label": "Run with markup",
      "download_from": "sales_review.xlsx" }
  ],
  "data_scale": { "max_files": 120, "max_total_bytes": 314572800,
                  "max_file_bytes": 20971520 },
  "engine": "auto",
  "write_back": true
}

{
  "schema_version": 1,
  "tables": {
    "orders": {
      "sources": [{"file": "Sales_2026_w*.xlsx", "sheet": "data", "header_row": 1}],
      "columns": {
        "region":      {"type": "text",   "role": "dim",     "source": "Region"},
        "client_code": {"type": "text",   "role": "dim",     "source": "Customer code"},
        "week":        {"type": "number", "role": "time",    "source": "Week"},
        "ordered":     {"type": "number", "role": "measure", "source": "Ordered"},
        "shipped":     {"type": "number", "role": "measure", "source": "Shipped"}
      }
    }
  },
  "kpis": {
    "fill_rate": {
      "name": "Order fill rate",
      "short": "Fill rate",
      "unit": null,
      "measure": "ratio",
      "question_forms": ["what is the order fill rate", "how much of the order was fulfilled"],
      "cell_sql": "SELECT region, client_code, week, SUM(LEAST(shipped, ordered)) AS n, SUM(ordered) AS d FROM orders GROUP BY 1, 2, 3"
    }
  }
}

